-- ---------------------------------------------------------------------------
-- team_assignments
-- ---------------------------------------------------------------------------
create table public.team_assignments (
  id             uuid primary key default gen_random_uuid(),
  assignee       text not null,                    -- 'Editor', 'Caleb', ...
