-- NevadoMedia BI Dashboard — Row Level Security
-- Run after 0001_schema.sql.
--
-- Model:
--   admin    (Sebastian) — everything.
--   operator (Nico)      — operations only. No retainer amounts, no expenses,
--                          no Stripe, no weekly revenue.
--   anon                 — nothing, except inserting its own funnel events.
--   service_role         — bypasses RLS entirely; used only by the VPS worker.

-- ---------------------------------------------------------------------------
-- Role helpers. SECURITY DEFINER so that reading profiles inside a profiles
-- policy does not recurse.
-- ---------------------------------------------------------------------------
create or replace function public.current_app_role()
returns user_role
language sql
stable
security definer
set search_path = public
as ' select role from public.profiles where id = auth.uid() ';

create or replace function public.is_admin()
returns boolean
language sql
stable
security definer
set search_path = public
as ' select coalesce(public.current_app_role() = ''admin'', false) ';

create or replace function public.is_staff()
returns boolean
language sql
stable
security definer
set search_path = public
as ' select public.current_app_role() is not null ';

grant execute on function public.current_app_role() to authenticated;
grant execute on function public.is_admin() to authenticated;
grant execute on function public.is_staff() to authenticated;

-- ---------------------------------------------------------------------------
-- Enable RLS everywhere. Default-deny: a table with RLS on and no matching
-- policy returns zero rows.
-- ---------------------------------------------------------------------------


alter table public.profiles enable row level security;
alter table public.profiles force row level security;
alter table public.clients enable row level security;
alter table public.clients force row level security;
alter table public.onboarding_checklist enable row level security;
alter table public.onboarding_checklist force row level security;
alter table public.content_pipeline enable row level security;
alter table public.content_pipeline force row level security;
alter table public.weekly_metrics enable row level security;
alter table public.weekly_metrics force row level security;
alter table public.expenses enable row level security;
alter table public.expenses force row level security;
alter table public.sales_pipeline enable row level security;
alter table public.sales_pipeline force row level security;
alter table public.team_assignments enable row level security;
alter table public.team_assignments force row level security;
alter table public.lead_response_log enable row level security;
alter table public.lead_response_log force row level security;
alter table public.client_communication_log enable row level security;
alter table public.client_communication_log force row level security;
alter table public.funnel_events enable row level security;
alter table public.funnel_events force row level security;
alter table public.ad_accounts enable row level security;
alter table public.ad_accounts force row level security;
alter table public.meta_insights_daily enable row level security;
alter table public.meta_insights_daily force row level security;
alter table public.metricool_daily enable row level security;
alter table public.metricool_daily force row level security;
alter table public.metricool_posts enable row level security;
alter table public.metricool_posts force row level security;
alter table public.fathom_calls enable row level security;
alter table public.fathom_calls force row level security;
alter table public.stripe_payments enable row level security;
alter table public.stripe_payments force row level security;
alter table public.calendar_events enable row level security;
alter table public.calendar_events force row level security;
alter table public.notion_client_status enable row level security;
alter table public.notion_client_status force row level security;
alter table public.sync_runs enable row level security;
alter table public.sync_runs force row level security;
alter table public.quick_actions enable row level security;
alter table public.quick_actions force row level security;

-- ---------------------------------------------------------------------------
-- profiles
-- ---------------------------------------------------------------------------
create policy "read own profile" on public.profiles
  for select to authenticated using (id = auth.uid());

create policy "admin reads all profiles" on public.profiles
  for select to authenticated using (public.is_admin());

create policy "admin writes profiles" on public.profiles
  for all to authenticated using (public.is_admin()) with check (public.is_admin());

-- ---------------------------------------------------------------------------
-- Admin-only tables (money)
-- ---------------------------------------------------------------------------


create policy "admin only" on public.clients
  for all to authenticated
  using (public.is_admin()) with check (public.is_admin());
create policy "admin only" on public.expenses
  for all to authenticated
  using (public.is_admin()) with check (public.is_admin());
create policy "admin only" on public.weekly_metrics
  for all to authenticated
  using (public.is_admin()) with check (public.is_admin());
create policy "admin only" on public.stripe_payments
  for all to authenticated
  using (public.is_admin()) with check (public.is_admin());

-- Operators reach clients through this column-filtered view instead. The view
-- runs with the owner's rights, so it is not blocked by the policy above, and
-- because it is a simple view it is auto-updatable — an operator can edit the
-- operational columns and cannot see or touch the financial ones.
create view public.clients_ops
with (security_barrier) as
select
  id, name, service, contract_start, renewal_date, last_touchpoint,
  next_action, next_action_due, goals, goal_progress, at_risk, notes,
  ball_side, location, active, created_at, updated_at
from public.clients;

-- Supabase's default privileges grant ALL on every new object in `public` to
-- anon and authenticated, so the grant below must be preceded by a revoke —
-- otherwise an operator could INSERT and DELETE client rows through the view.
revoke all on public.clients_ops from anon, authenticated;
grant select, update on public.clients_ops to authenticated;

-- ---------------------------------------------------------------------------
-- Operational tables — both roles read and write
-- ---------------------------------------------------------------------------


create policy "staff read" on public.onboarding_checklist for select to authenticated
  using (public.is_staff());
create policy "staff write" on public.onboarding_checklist for all to authenticated
  using (public.is_staff()) with check (public.is_staff());
create policy "staff read" on public.content_pipeline for select to authenticated
  using (public.is_staff());
create policy "staff write" on public.content_pipeline for all to authenticated
  using (public.is_staff()) with check (public.is_staff());
create policy "staff read" on public.sales_pipeline for select to authenticated
  using (public.is_staff());
create policy "staff write" on public.sales_pipeline for all to authenticated
  using (public.is_staff()) with check (public.is_staff());
create policy "staff read" on public.team_assignments for select to authenticated
  using (public.is_staff());
create policy "staff write" on public.team_assignments for all to authenticated
  using (public.is_staff()) with check (public.is_staff());
create policy "staff read" on public.lead_response_log for select to authenticated
  using (public.is_staff());
create policy "staff write" on public.lead_response_log for all to authenticated
  using (public.is_staff()) with check (public.is_staff());
create policy "staff read" on public.client_communication_log for select to authenticated
  using (public.is_staff());
create policy "staff write" on public.client_communication_log for all to authenticated
  using (public.is_staff()) with check (public.is_staff());
create policy "staff read" on public.quick_actions for select to authenticated
  using (public.is_staff());
create policy "staff write" on public.quick_actions for all to authenticated
  using (public.is_staff()) with check (public.is_staff());

-- ---------------------------------------------------------------------------
-- Synced tables — staff read, worker writes with service_role
-- ---------------------------------------------------------------------------


create policy "staff read" on public.ad_accounts for select to authenticated
  using (public.is_staff());
create policy "staff read" on public.meta_insights_daily for select to authenticated
  using (public.is_staff());
create policy "staff read" on public.metricool_daily for select to authenticated
  using (public.is_staff());
create policy "staff read" on public.metricool_posts for select to authenticated
  using (public.is_staff());
create policy "staff read" on public.fathom_calls for select to authenticated
  using (public.is_staff());
create policy "staff read" on public.calendar_events for select to authenticated
  using (public.is_staff());
create policy "staff read" on public.notion_client_status for select to authenticated
  using (public.is_staff());
create policy "staff read" on public.sync_runs for select to authenticated
  using (public.is_staff());

-- Two exceptions where a human edits synced data by hand.
create policy "admin edits ad accounts" on public.ad_accounts
  for all to authenticated using (public.is_admin()) with check (public.is_admin());

-- Correcting a Fathom auto-classification must stick across re-syncs.
create policy "staff reclassifies calls" on public.fathom_calls
  for update to authenticated
  using (public.is_staff()) with check (public.is_staff());

-- ---------------------------------------------------------------------------
-- funnel_events — the public landing page writes here anonymously
-- ---------------------------------------------------------------------------
create policy "staff read funnel" on public.funnel_events
  for select to authenticated using (public.is_staff());

-- Anonymous visitors may only append, never read back.
create policy "visitor appends funnel event" on public.funnel_events
  for insert to anon with check (
    session_id is not null and length(session_id) between 8 and 64
  );

-- ---------------------------------------------------------------------------
-- sync_freshness view inherits sync_runs' policy through the base table.
-- ---------------------------------------------------------------------------
alter view public.sync_freshness set (security_invoker = true);
revoke all on public.sync_freshness from anon, authenticated;
grant select on public.sync_freshness to authenticated;
-- Phase 3 additions: things the manual-input sections need that phase 1 did not
-- anticipate. Run after 0002_rls.sql.

-- ---------------------------------------------------------------------------
-- When a client relationship ended. Churn is "lost this month vs signed this
-- month", and without this there is no way to date a loss — `active` alone
-- says the state, not when it changed.
-- ---------------------------------------------------------------------------
alter table public.clients add column if not exists ended_at date;

-- ---------------------------------------------------------------------------
-- app_settings — small admin-owned key/value store. Revenue per head needs a
-- team headcount, which belongs to nobody else's table.
-- ---------------------------------------------------------------------------
create table if not exists public.app_settings (
  key        text primary key,
  value      jsonb not null,
  updated_at timestamptz not null default now()
);

alter table public.app_settings enable row level security;
alter table public.app_settings force row level security;

create policy "admin manages settings" on public.app_settings
  for all to authenticated
  using (public.is_admin()) with check (public.is_admin());

create trigger touch_app_settings before update on public.app_settings
  for each row execute function public.touch_updated_at();

insert into public.app_settings (key, value) values
  ('team_size', '3'::jsonb)
on conflict (key) do nothing;

